export const RTL_LANGS = new Set(['ar', 'fa']);

export function t(lang, key, vars = {}) {
  const str = (translations[lang] ?? translations.en)[key] ?? translations.en[key] ?? key;
  return str.replace(/\{(\w+)\}/g, (_, k) => vars[k] ?? '');
}
